import csv
import json
import os

def main():
    input_path = '/work/data.csv'
    output_path = '/work/result.json'

    if not os.path.exists(input_path):
        raise ValueError(f"Input file {input_path} not found")

    groups = {}
    row_count = 0

    with open(input_path, 'r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            row_count += 1
            channel = row.get('channel')
            revenue_str = row.get('revenue')

            if channel is None or revenue_str is None:
                continue

            try:
                revenue = float(revenue_str)
            except ValueError:
                continue

            if channel not in groups:
                groups[channel] = 0.0
            groups[channel] += revenue

    # Prepare list of groups, limiting to 24
    group_list = []
    for label, value in groups.items():
        group_list.append({
            "label": str(label),
            "value": float(value)
        })

    # Sort by value descending for better presentation, though not strictly required
    group_list.sort(key=lambda x: x['value'], reverse=True)

    # Limit to 24 groups
    group_list = group_list[:24]

    total = sum(g['value'] for g in group_list)

    result = {
        "rows": row_count,
        "groups": group_list,
        "total": total
    }

    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(result, f, indent=2)

if __name__ == '__main__':
    main()
